INSERT INTO template (name, contract_type_code, jurisdiction_code, language_code, status, body_html, description)
VALUES (
  'Vendor Purchase Agreement (EN)', 'VENDOR_PURCHASE', 'GLOBAL', 'en', 'ACTIVE',
  '<h1>VENDOR PURCHASE AGREEMENT</h1><p>This Vendor Purchase Agreement (the "Agreement") is entered into as of this ___ day of ____________, 20___ (the "Effective Date"), by and between: <b>{{entity_name}}</b>, with its principal place of business at _________________________________ ("Buyer"), and <b>{{counterparty_name}}</b>, with its principal place of business at _________________________________ ("Vendor").</p><p>Buyer and Vendor are each referred to individually as a "Party" and collectively as the "Parties."</p><p>RECITALS</p><p>WHEREAS, Buyer desires to purchase certain goods and/or services from Vendor; and</p><p>WHEREAS, Vendor is willing to supply such goods and/or services on the terms set out in this Agreement;</p><p>NOW, THEREFORE, in consideration of the mutual covenants contained herein, the Parties agree as follows:</p><p>1. SCOPE OF PURCHASE</p><p>1.1 Vendor shall supply to Buyer the goods and/or services described in Schedule A attached hereto (the "Deliverables"), in accordance with the specifications, quantities and delivery terms set out therein.</p><p>1.2 Any change to the Deliverables must be agreed in writing by both Parties before it becomes effective.</p><p>2. PRICE AND PAYMENT</p><p>2.1 The total purchase price for the Deliverables shall be as set out in Schedule A. Unless otherwise agreed in writing, the price is inclusive of packaging but exclusive of applicable taxes.</p><p>2.2 Buyer shall pay undisputed invoices within <b>{{payment_terms_days}}</b> days of receipt, by bank transfer to the account nominated in writing by Vendor.</p><p>2.3 Vendor may not suspend deliveries for any disputed amount while the dispute is being resolved in good faith.</p><p>3. DELIVERY AND ACCEPTANCE</p><p>3.1 Delivery shall be made to the Buyer facility nominated in the purchase order, in accordance with the agreed delivery schedule.</p><p>3.2 Buyer shall have ___ business days from receipt to inspect the Deliverables. Deliverables that do not conform to the specifications may be rejected, and Vendor shall repair or replace them at its own cost.</p><p>4. WARRANTIES</p><p>4.1 Vendor warrants that (a) it has full right and authority to sell the Deliverables; (b) the Deliverables will conform to the agreed specifications and be free from defects in material and workmanship; and (c) the Deliverables do not infringe any third-party intellectual-property rights.</p><p>5. TERM AND TERMINATION</p><p>5.1 This Agreement commences on the Effective Date and continues until ___ unless terminated earlier in accordance with this Section.</p><p>5.2 Either Party may terminate for material breach not cured within thirty (30) days of written notice. Buyer may terminate for convenience upon thirty (30) days'' written notice, paying only for Deliverables properly delivered to date.</p><p>6. CONFIDENTIALITY</p><p>6.1 Each Party shall keep the other''s non-public information confidential and use it only for the purposes of this Agreement. This obligation survives termination for three (3) years.</p><p>7. LIABILITY</p><p>7.1 Neither Party is liable for indirect or consequential loss. Vendor''s aggregate liability under this Agreement shall not exceed the amounts paid or payable under it in the twelve (12) months preceding the claim.</p><p>8. GOVERNING LAW</p><p>8.1 This Agreement is governed by the laws of <b>{{governing_law}}</b>, and the Parties submit to the exclusive jurisdiction of its courts.</p><p>SCHEDULE A — DELIVERABLES, SPECIFICATIONS, PRICE AND DELIVERY TERMS</p><p>[To be completed and agreed in writing by both Parties at the time of order.]</p>',
  'Standard vendor purchase agreement (goods and/or services) with delivery, acceptance, warranty and liability terms.'
) ON CONFLICT DO NOTHING;